def pos(row, col):
    """Return the ANSI escape sequence to move the cursor to position (row, col)."""
    return f"\x1b[{row};{col}H"


def up(n=1):
    """Return the ANSI escape sequence to move the cursor up by n lines."""
    return f"\x1b[{n}A"


def down(n=1):
    """Return the ANSI escape sequence to move the cursor down by n lines."""
    return f"\x1b[{n}B"


def right(n=1):
    """Return the ANSI escape sequence to move the cursor right by n columns."""
    return f"\x1b[{n}C"


def left(n=1):
    """Return the ANSI escape sequence to move the cursor left by n columns."""
    return f"\x1b[{n}D"


def fg_rgb(r, g, b):
    """Return a truecolor foreground escape sequence for an RGB tuple."""
    return f"\x1b[38;2;{r};{g};{b}m"


def bg_rgb(r, g, b):
    """Return a truecolor background escape sequence for an RGB tuple."""
    return f"\x1b[48;2;{r};{g};{b}m"


def fg_rgbd(r, g, b):
    """Return a bold truecolor foreground escape sequence for an RGB tuple."""
    return f"\x1b[1;38;2;{r};{g};{b}m"


def bg_rgbd(r, g, b):
    """Return a bold truecolor background escape sequence for an RGB tuple."""
    return f"\x1b[1;48;2;{r};{g};{b}m"
